 useEffect(()=>{if(!user)return;const s=io({withCredentials:true});sock.current=s;s.on('world:snapshot',q=>setOnline(q.filter(x=>x.id!==user.id)));s.on('world:count',setWorldCount);s.on('player:joined',q=>setOnline(a=>[...a.filter(x=>x.id!==q.id),q]));s.on('player:moved',q=>setOnline(a=>a.map(x=>x.id===q.id?{...x,...q}:x)));s.on('player:update',q=>q.id===user.id?updatePlayer(q):setOnline(a=>a.map(x=>x.id===q.id?{...x,...q}:x)));s.on('player:left',q=>setOnline(a=>a.filter(x=>x.id!==q.id)));s.on('chat:history',setMessages);s.on('chat:message',q=>setMessages(a=>[...a.slice(-39),q]));s.on('chat:hidden',q=>setMessages(a=>a.filter(x=>x.id!==q.id)));s.on('crew:lobby',setCrewLobby);s.on('crew:round',q=>{setCrewRound(q);setCrewMeeting(null);setCrewResult(null);setCrewOpen(true)});s.on('crew:meeting',q=>{setCrewMeeting(q);setCrewVoteCount(0)});s.on('crew:vote-count',q=>setCrewVoteCount(q.count));s.on('crew:result',q=>{setCrewResult(q);setCrewMeeting(null);setCrewRound(null)});s.on('connect_error',()=>setServerError('Could not join the live city. Check the server and sign in again.'));return()=>{s.disconnect();sock.current=null}},[user?.id,updatePlayer]);
 useEffect(()=>{const clear=()=>{keys.current={}},down=e=>{if(['1','2','3'].includes(e.key)&&!['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)){setCameraMode(['orbit','drone','walk'][Number(e.key)-1]);setMapExplorerOpen(true);return}if(e.key.toLowerCase()==='c'&&!['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)){e.preventDefault();setInVehicle(v=>!v);return}if(e.key.toLowerCase()==='e'&&nearbyNpc&&!['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)){e.preventDefault();speakToNpc(0);return}if(e.key===' '&&!['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)){e.preventDefault();p.current.jumpUntil=performance.now()+520;return}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d','W','A','S','D','Enter'].includes(e.key)&&!['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)){e.preventDefault();if(e.key==='Enter'&&user)setChat(true);else keys.current[e.key]=true}},up=e=>keys.current[e.key]=false;addEventListener('keydown',down);addEventListener('keyup',up);addEventListener('blur',clear);document.addEventListener('visibilitychange',clear);return()=>{removeEventListener('keydown',down);removeEventListener('keyup',up);removeEventListener('blur',clear);document.removeEventListener('visibilitychange',clear)}},[user,nearbyNpc]);
 useEffect(()=>{let raf;const frame=t=>{raf=requestAnimationFrame(frame);const dt=Math.min((t-last.current.frame)/1000,.05);last.current.frame=t;let dx=0,dy=0;const k=keys.current,pad=navigator.getGamepads?.()?.find(g=>g&&g.connected),speed=inVehicle?280:(k.Shift?132:80);if(pad){dx=pad.axes[0]||0;dy=pad.axes[1]||0;if(Math.abs(dx)<.2)dx=0;if(Math.abs(dy)<.2)dy=0;if(pad.buttons[0]?.pressed)p.current.jumpUntil=t+520}const oldX=p.current.x,oldY=p.current.y;if(k.ArrowLeft||k.a||k.A)dx--;if(k.ArrowRight||k.d||k.D)dx++;if(k.ArrowUp||k.w||k.W)dy--;if(k.ArrowDown||k.s||k.S)dy++;if(dx||dy){const n=Math.hypot(dx,dy);p.current.x+=dx/n*speed*dt;p.current.y+=dy/n*speed*dt;p.current.tx=p.current.x;p.current.ty=p.current.y;p.current.heading=Math.atan2(-dx,-dy)}else{const x=p.current.tx-p.current.x,y=p.current.ty-p.current.y,n=Math.hypot(x,y);if(n>4){p.current.x+=x/n*Math.min(n,(inVehicle?360:100)*dt);p.current.y+=y/n*Math.min(n,(inVehicle?360:100)*dt);p.current.heading=Math.atan2(-x,-y)}}const hit=obstacles.current.some(b=>Math.abs(p.current.x-b.x)<b.rx&&Math.abs(p.current.y-b.y)<b.ry);if(hit){p.current.x=oldX;p.current.y=oldY;p.current.tx=oldX;p.current.ty=oldY}p.current.inVehicle=inVehicle;p.current.x=Math.max(WORLD.minX,Math.min(WORLD.maxX,p.current.x));p.current.y=Math.max(WORLD.minY,Math.min(WORLD.maxY,p.current.y));if(sock.current?.connected&&t-last.current.move>120){last.current.move=t;sock.current.emit('player:move',{x:p.current.x,y:p.current.y,heading:p.current.heading,inVehicle})}if(active){const n=Math.hypot(active.x-p.current.x,active.y-p.current.y)<=145;setNear(q=>q===n?q:n)}};raf=requestAnimationFrame(frame);return()=>cancelAnimationFrame(raf)},[active,inVehicle]);
