 const enterBuilding=()=>{if(!active)return;if(!near){setNotice(`Walking to ${active.name}'s entrance…`);return}const seen=[...new Set([...visitedBuildings,active.id])];setVisitedBuildings(seen);localStorage.setItem('blank-life-visited',JSON.stringify(seen));setInterior(active);setActivityNotice('');setNotice(`You entered your selected building: ${active.name}.`)};
 const doBuildingActivity=async activity=>{if(!interior)return;if(interior.job){const career=jobs.find(j=>j.id===interior.id);if(!user){openAuth('signup');return}if(player.jobId!==career?.id){try{await selectJob(career);setInterior(null);setNotice(`${career.title} selected. Walk to ${career.studio} to start your first task.`)}catch{}return}await completeJob();setActivityNotice(`Task complete · +₦${jobs.find(j=>j.id===player.jobId)?.reward||0} and career XP`);return}if(interior.generated){setActivityNotice(`${activity.label} · You spent some time at ${interior.name}. Building activities are ready for your future venue design.`);setNotice(`${activity.label} at ${interior.name}.`);return}if(interior.kind==='Work & learn'&&activity.label.toLowerCase().includes('career board')){setInterior(null);setJobsOpen(true);return}const gamePoints=interior.kind==='Games'&&activity.label.toLowerCase().includes('round')?10+Math.floor(Math.random()*91):0;if(!user){if(gamePoints)setMiniGameScore(s=>s+gamePoints);setActivityNotice(`${activity.label}${gamePoints?` · You scored ${gamePoints} arcade points (total ${miniGameScore+gamePoints})`:''} · Guest activity. Create an account to save your progress and earn pocket money.`);setNotice(`${activity.label} at ${interior.name}.`);return}setBusy(true);try{const d=await api('/api/visit',{method:'POST',body:JSON.stringify({placeId:interior.id,activityId:activity.id})});updatePlayer(d.player);if(gamePoints)setMiniGameScore(s=>s+gamePoints);setActivityNotice(`${d.activity} · +₦${d.reward}${gamePoints?` · ${gamePoints} arcade points (total ${miniGameScore+gamePoints})`:''} · mood improved`);setNotice(`${d.activity} · +₦${d.reward}`)}catch(err){setNotice(err.message)}finally{setBusy(false)}};
 const buy=async q=>{if(!user){openAuth('signup');return}try{const d=await api(`/api/homes/${q.id}/buy`,{method:'POST'});updatePlayer(d.player);setOwned(a=>[...a,q.id]);setHomes(a=>a.map(x=>x.id===q.id?{...x,owned:true,ownerId:user.id}:x));setNotice(`${q.name} is yours. Welcome home!`)}catch(err){setNotice(err.message)}};
 const sendChat=e=>{e.preventDefault();if(!user){openAuth('signup');return}if(chatText.trim()){sock.current?.emit('chat:send',chatText.trim());setChatText('')}};
 const requestDispatch=kind=>{const id=Date.now(),destination=active?.name||'your current location';setDispatch({id,kind,destination,status:'finding',eta:2+Math.floor(Math.random()*4)});setNotice(`${kind} dispatch requested for ${destination}.`);setTimeout(()=>setDispatch(q=>q?.id===id?{...q,status:'assigned'}:q),1600)};
 const searchWeb=e=>{e.preventDefault();const query=webQuery.trim();if(!query)return;window.open(`https://www.google.com/search?q=${encodeURIComponent(query)}`,'_blank','noopener,noreferrer')};
 const report=async id=>{try{await api(`/api/chat/${id}/report`,{method:'POST',body:JSON.stringify({reason:'Inappropriate or unsafe'})});setNotice('Thanks. Your report was sent to moderators.')}catch(err){setNotice(err.message)}};
