 const selectJob=async q=>{if(!user){openAuth('signup');return}try{const d=await api('/api/jobs/select',{method:'POST',body:JSON.stringify({jobId:q.id})});updatePlayer(d.player);travel({...q,job:true});setJobsOpen(false);setNotice(`${q.title} selected · head to ${q.studio}`)}catch(err){setNotice(err.message)}};
