 const completeLesson=async(lessonId,answer)=>{if(!user){const lesson=lessons.find(x=>x.id===lessonId);if(!lesson||answer!==lesson.answer)return{correct:false,explanation:lesson?.explanation};const next=[...new Set([...learningCompleted,lessonId])];setLearningCompleted(next);localStorage.setItem('blank-life-learning',JSON.stringify(next));return{correct:true,explanation:lesson.explanation}}const result=await api('/api/learning/complete',{method:'POST',body:JSON.stringify({lessonId,answer})});if(result.correct){if(result.player)updatePlayer(result.player);if(!result.already)setLearningCompleted(a=>a.includes(lessonId)?a:[...a,lessonId])}return result};
