  <div className="right-stack"><div className="player-card"><div className="player-avatar" onClick={()=>user?openAuth('edit'):openAuth('signup')}>{avatars[player.avatar]}</div><div className="player-id"><small>{user?'YOUR DEVELOPER':'GUEST MODE'}</small><b>{player.name}</b><span>{user?(jobs.find(j=>j.id===player.jobId)?.title||'Choose a career'):'Create an account to save progress'}</span></div><span className="hunter-grade">{(player.xp||0)>=2500?'S':(player.xp||0)>=2000?'A':(player.xp||0)>=1500?'B':(player.xp||0)>=1000?'C':(player.xp||0)>=500?'D':'E'}<small>RANK</small></span><button className="player-more" onClick={()=>user?openAuth('edit'):openAuth('signup')}><ChevronDown size={16}/></button></div><div className="stat-card"><div className="stat-row"><span>₦</span><div><small>POCKET MONEY</small><b>{user?player.coins.toLocaleString():'Sign in to earn'}</b></div><Coins size={16}/></div>{user&&<div className="career-xp"><span>CAREER XP</span><b>{player.xp||0}</b></div>}<div className="meter"><span style={{width:`${player.energy}%`}}/></div><div className="meter-label"><span>⚡ Energy</span><b>{player.energy}%</b></div><div className="meter mood"><span style={{width:`${player.mood}%`}}/></div><div className="meter-label"><span>💚 Mood</span><b>{player.mood}%</b></div></div>{active&&<div className="spot-card"><button className="spot-close" onClick={()=>{setActive(null);setInterior(null)}}><X size={16}/></button><div className="spot-card-top"><span className="spot-card-icon" style={{'--spot':active.color||'#57a982'}}>{active.emoji||'🏛️'}</span><div><small>{active.buildingRole||active.kind} · {active.district||'Yaba Dev District'}</small><h2>{active.name}</h2></div></div><p>{active.uses||active.description}</p><button className="visit-button" onClick={enterBuilding} disabled={!near}><DoorOpen size={16}/>{near?'Enter building':'Walking to entrance…'}<span>{near?'Open to all players':''}</span></button></div>}</div>
