  {nearbyNpc&&<button className="npc-talk-prompt" onClick={()=>speakToNpc(0)}><MessageCircle size={15}/><span>Talk to {nearbyNpc.name}</span><kbd>E</kbd></button>}{dialogueOpen&&nearbyNpc&&<aside className="npc-dialogue"><button className="npc-dialogue-close" onClick={()=>setDialogueOpen(false)} aria-label="Close conversation"><X size={15}/></button><span className="modal-kicker">{nearbyNpc.role} · NORTH COAST OUTPOST</span><h3>{nearbyNpc.name}</h3><p>{dialogueLine||nearbyNpc.dialogue[0]}</p><div><button onClick={()=>speakToNpc(1)}>Ask about developer work</button><button onClick={()=>speakToNpc(2)}>Ask about island supplies</button></div></aside>}{crewOpen&&<section className="crew-panel"><button className="crew-close" onClick={()=>setCrewOpen(false)}><X size={16}/></button><span className="modal-kicker">LIVE SOCIAL DEDUCTION</span><h3>Trust Protocol</h3>{crewResult?<><p className="crew-outcome">{crewResult.winner==='crew'?'🟢 Crew restored the build!':'🔴 The saboteur slipped away.'}</p><p>{crewResult.ejected?`${crewResult.ejected} was voted out.`:'No one was voted out.'}</p><button className="crew-primary" onClick={startCrew}>Start another round</button></>:crewMeeting?<><p>{crewMeeting.reason}</p><small>Votes in: {crewVoteCount}/{crewMeeting.players.length}</small><div className="crew-vote-list">{crewMeeting.players.filter(q=>q.id!==user?.id).map(q=><button key={q.id} onClick={()=>crewVote(q.id)}>{q.name}<span>Vote out</span></button>)}</div><p className="crew-tip">Talk it over in neighbourhood chat before voting.</p></>:crewRound?<><p className="crew-role">Your secret role: <b>{crewRound.role==='saboteur'?'🟥 Saboteur':'🟩 Crew developer'}</b></p><p>{crewRound.role==='saboteur'?'Trigger a build incident, then blend in.':'Ship tasks, report suspicious activity, and find the saboteur.'}</p><div className="crew-player-list">{crewRound.players.map(q=><span key={q.id}>{q.name}</span>)}</div>{crewRound.role==='saboteur'?<button className="crew-primary danger" onClick={makeSabotage}>Trigger build incident</button>:<button className="crew-primary" onClick={reportAnomaly}>Report anomaly</button>}</>:<><p>A secret saboteur is hiding in the dev crew. Work together, discuss clues, and vote.</p><div className="crew-count"><Users size={17}/>{user?worldCount:0} / 3 developers online</div><button className="crew-primary" onClick={startCrew} disabled={!user||crewLobby.online<3||crewLobby.active}>{!user?'Sign in to join':crewLobby.active?'Round in progress':crewLobby.online<3?'Need 3 online developers':'Start a mystery round'}</button><p className="crew-tip">Original social deduction mode. Invite friends to play.</p></>}</section>}
  <div className="bottom-left"><div className="speech-bubble"><MessageCircle size={15}/><span>{notice}</span></div><div className="quick-actions"><button onClick={()=>user?setChat(!chat):openAuth('signup')}><MessageCircle size={17}/><span>Chat</span><kbd>Enter</kbd></button><button onClick={()=>setNotice(`${online.length} Lagosian${online.length===1?'':'s'} currently online.`)}><Users size={17}/><span>People {user?online.length:''}</span></button><button onClick={()=>{setPhoneOpen(v=>!v);setPhoneView('home')}}><Smartphone size={17}/><span>Phone</span></button><button onClick={()=>setMapOpen(!mapOpen)}><MapPin size={17}/><span>Places</span></button></div></div>
